# Logic gate functions
def AND(a, b):
    return a & b

def OR(a, b):
    return a | b

def NOT(a):
    return 1 - a  # 1 - 1 = 0, 1 - 0 = 1

def XOR(a, b):
    return a ^ b

def NAND(a, b):
    return NOT(AND(a, b))

def NOR(a, b):
    return NOT(OR(a, b))

# Test all combinations
print('A B | AND OR XOR NAND')
print('----------------------')
for a in [0, 1]:
    for b in [0, 1]:
        print(f'{a} {b} |  {AND(a,b)}   {OR(a,b)}   {XOR(a,b)}    {NAND(a,b)}')

# Build half adder
def half_adder(a, b):
    sum_bit = XOR(a, b)
    carry = AND(a, b)
    return sum_bit, carry

print('\nHalf Adder:')
print('A B | Sum Carry')
for a in [0, 1]:
    for b in [0, 1]:
        s, c = half_adder(a, b)
        print(f'{a} {b} |  {s}     {c}')
